using Microsoft.Data.Sqlite;
using System.Globalization;
using System.Text.Json;
namespace TornCommander;
internal sealed record ItemObservation(string Source,string Location,int ItemId,string Name,DateTime ObservedUtc,DateTime CollectedUtc,int Quantity,long Cost,long? MarketValue=null,string Kind="foreign-shop");
internal sealed record ProviderHealth(string Source,string Status,DateTime? LastSuccessUtc,DateTime? NextAttemptUtc,string Detail);
internal sealed class IntelligenceStore
{
    private readonly string _path;
    public IntelligenceStore(string path){_path=path;Directory.CreateDirectory(Path.GetDirectoryName(path)!);using var db=Open();using(var version=db.CreateCommand()){version.CommandText="PRAGMA user_version";if(Convert.ToInt32(version.ExecuteScalar())>1)throw new InvalidDataException("Newer intelligence database schema; update Commander.");}using var c=db.CreateCommand();c.CommandText="""
        PRAGMA journal_mode=WAL;
        CREATE TABLE IF NOT EXISTS item_observations(source TEXT NOT NULL,location TEXT NOT NULL,item_id INTEGER NOT NULL,name TEXT NOT NULL,observed TEXT NOT NULL,collected TEXT NOT NULL,quantity INTEGER NOT NULL,cost INTEGER NOT NULL,market INTEGER,kind TEXT NOT NULL,PRIMARY KEY(source,location,item_id,observed));
        CREATE TABLE IF NOT EXISTS item_latest AS SELECT * FROM item_observations WHERE 0;
        CREATE UNIQUE INDEX IF NOT EXISTS ix_item_latest ON item_latest(source,location,item_id);
        CREATE INDEX IF NOT EXISTS ix_item_time ON item_observations(item_id,location,observed);
        CREATE TABLE IF NOT EXISTS snapshots(profile TEXT NOT NULL,kind TEXT NOT NULL,entity TEXT NOT NULL,observed TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(profile,kind,entity,observed));
        CREATE TABLE IF NOT EXISTS configuration(profile TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(profile,kind));
        PRAGMA user_version=1;
        """;c.ExecuteNonQuery();}
    private SqliteConnection Open(){var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=_path,Mode=SqliteOpenMode.ReadWriteCreate,DefaultTimeout=5}.ToString());db.Open();return db;}
    private static string Stamp(DateTime t)=>t.ToUniversalTime().ToString("O",CultureInfo.InvariantCulture);
    public int Add(IEnumerable<ItemObservation> rows,DateTime now){using var db=Open();using var tx=db.BeginTransaction();int count=0;foreach(var x in rows){if(x.ItemId<=0||x.Quantity<0||x.Cost<0||x.MarketValue<0||x.ObservedUtc>now.AddMinutes(2)||x.ObservedUtc<now.AddDays(-366)||x.Location.Length is <1 or >80||x.Source.Length is <1 or >160||x.Name.Length is <1 or >160)throw new InvalidDataException("Invalid or out-of-range observation; import was rolled back.");using var c=db.CreateCommand();c.Transaction=tx;c.CommandText="INSERT OR IGNORE INTO item_observations VALUES($s,$l,$i,$n,$o,$c,$q,$b,$m,$k)";c.Parameters.AddWithValue("$s",x.Source);c.Parameters.AddWithValue("$l",x.Location);c.Parameters.AddWithValue("$i",x.ItemId);c.Parameters.AddWithValue("$n",x.Name);c.Parameters.AddWithValue("$o",Stamp(x.ObservedUtc));c.Parameters.AddWithValue("$c",Stamp(x.CollectedUtc));c.Parameters.AddWithValue("$q",x.Quantity);c.Parameters.AddWithValue("$b",x.Cost);c.Parameters.AddWithValue("$m",(object?)x.MarketValue??DBNull.Value);c.Parameters.AddWithValue("$k",x.Kind);count+=c.ExecuteNonQuery();
        using var latest=db.CreateCommand();latest.Transaction=tx;latest.CommandText="INSERT INTO item_latest SELECT * FROM item_observations WHERE source=$s AND location=$l AND item_id=$i AND observed=$o ON CONFLICT(source,location,item_id) DO UPDATE SET name=excluded.name,observed=excluded.observed,collected=excluded.collected,quantity=excluded.quantity,cost=excluded.cost,market=excluded.market,kind=excluded.kind WHERE excluded.observed>item_latest.observed";latest.Parameters.AddWithValue("$s",x.Source);latest.Parameters.AddWithValue("$l",x.Location);latest.Parameters.AddWithValue("$i",x.ItemId);latest.Parameters.AddWithValue("$o",Stamp(x.ObservedUtc));latest.ExecuteNonQuery();}tx.Commit();return count;}
    public List<ItemObservation> Read(int? item=null,string? location=null,int days=90){using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT source,location,item_id,name,observed,collected,quantity,cost,market,kind FROM item_observations WHERE observed>=$after AND ($id IS NULL OR item_id=$id) AND ($loc IS NULL OR location=$loc) ORDER BY observed DESC LIMIT 150000";c.Parameters.AddWithValue("$after",Stamp(DateTime.UtcNow.AddDays(-Math.Clamp(days,1,365))));c.Parameters.AddWithValue("$id",(object?)item??DBNull.Value);c.Parameters.AddWithValue("$loc",(object?)location??DBNull.Value);using var r=c.ExecuteReader();var rows=new List<ItemObservation>();while(r.Read())rows.Add(new(r.GetString(0),r.GetString(1),r.GetInt32(2),r.GetString(3),DateTime.Parse(r.GetString(4),null,DateTimeStyles.RoundtripKind),DateTime.Parse(r.GetString(5),null,DateTimeStyles.RoundtripKind),r.GetInt32(6),r.GetInt64(7),r.IsDBNull(8)?null:r.GetInt64(8),r.GetString(9)));rows.Reverse();return rows;}
    public List<ItemObservation> Latest(){using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT source,location,item_id,name,observed,collected,quantity,cost,market,kind FROM item_latest ORDER BY name";using var r=c.ExecuteReader();var rows=new List<ItemObservation>();while(r.Read())rows.Add(new(r.GetString(0),r.GetString(1),r.GetInt32(2),r.GetString(3),DateTime.Parse(r.GetString(4),null,DateTimeStyles.RoundtripKind),DateTime.Parse(r.GetString(5),null,DateTimeStyles.RoundtripKind),r.GetInt32(6),r.GetInt64(7),r.IsDBNull(8)?null:r.GetInt64(8),r.GetString(9)));return rows;}
    public long Count(){using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT COUNT(*) FROM item_observations";return Convert.ToInt64(c.ExecuteScalar());}
    public void Snapshot(string profile,string kind,string entity,DateTime observed,object payload){using var db=Open();using var c=db.CreateCommand();c.CommandText="INSERT OR REPLACE INTO snapshots VALUES($p,$k,$e,$o,$v)";c.Parameters.AddWithValue("$p",profile);c.Parameters.AddWithValue("$k",kind);c.Parameters.AddWithValue("$e",entity);c.Parameters.AddWithValue("$o",Stamp(observed));c.Parameters.AddWithValue("$v",JsonSerializer.Serialize(payload));c.ExecuteNonQuery();}
    public List<string> Snapshots(string profile,string kind,string entity,int limit=500){using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT payload FROM snapshots WHERE profile=$p AND kind=$k AND entity=$e ORDER BY observed DESC LIMIT $limit";c.Parameters.AddWithValue("$p",profile);c.Parameters.AddWithValue("$k",kind);c.Parameters.AddWithValue("$e",entity);c.Parameters.AddWithValue("$limit",Math.Clamp(limit,1,5000));using var r=c.ExecuteReader();var result=new List<string>();while(r.Read())result.Add(r.GetString(0));return result;}
    public T Load<T>(string profile,string kind,T fallback){using var db=Open();using var c=db.CreateCommand();c.CommandText="SELECT payload FROM configuration WHERE profile=$p AND kind=$k";c.Parameters.AddWithValue("$p",profile);c.Parameters.AddWithValue("$k",kind);var json=c.ExecuteScalar() as string;return json is null?fallback:JsonSerializer.Deserialize<T>(json)??fallback;}
    public void Save(string profile,string kind,object value){using var db=Open();using var c=db.CreateCommand();c.CommandText="INSERT OR REPLACE INTO configuration VALUES($p,$k,$v)";c.Parameters.AddWithValue("$p",profile);c.Parameters.AddWithValue("$k",kind);c.Parameters.AddWithValue("$v",JsonSerializer.Serialize(value));c.ExecuteNonQuery();}
    public void Prune(int days){using var db=Open();using var c=db.CreateCommand();c.CommandText="DELETE FROM item_observations WHERE observed<$cut";c.Parameters.AddWithValue("$cut",Stamp(DateTime.UtcNow.AddDays(-Math.Clamp(days,7,365))));c.ExecuteNonQuery();}
}
